package io.proleap.benchmark;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.time.LocalDate;
import java.util.*;
import java.util.regex.*;

final class ReportWriter {
    private static final List<String> INVENTORY = List.of("COPY","CALL","PERFORM","GO TO","IF","EVALUATE","EXEC SQL","EXEC CICS","EXEC SQLIMS","REDEFINES","OCCURS");
    private ReportWriter() {}

    static void write(BenchmarkData data) throws IOException {
        List<String> names = new ArrayList<>(data.aggregateFiles().keySet());
        List<FrontendResult> a = data.aggregateFiles().get(names.get(0)), b = data.aggregateFiles().get(names.get(1));
        String recommendation = recommendation(a, b);
        long totalLoc = a.stream().mapToLong(FrontendResult::sourceLines).sum();
        long totalBytes = a.stream().mapToLong(FrontendResult::sourceBytes).sum();
        long copyLoc = 0, copyBytes = 0;
        for (Path p : data.copybooks()) { copyLoc += Files.readString(p).lines().count(); copyBytes += Files.size(p); }
        List<Long> sizes = a.stream().map(FrontendResult::sourceLines).sorted().toList();
        StringBuilder r = new StringBuilder();
        r.append("# COBOL Grammar Bake-off\n\n");
        r.append("## 1. Executive Summary\n\n").append(summaryLine(a)).append("; ").append(summaryLine(b)).append(". ")
                .append("A recomendação considera cobertura antes de desempenho e vale **segundo este corpus e este experimento**.\n\n")
                .append("**RECOMMENDATION: ").append(recommendation).append("**\n\n");
        r.append("## 2. Question Being Evaluated\n\nQual par grammar + preprocessor é a melhor baseline sintática para `preprocessing → ANTLR parse tree → AstBuilder próprio`, sem ASG, metamodelo ou analisadores ProLeap.\n\n");
        r.append("## 3. Candidates\n\n### grammars-v4 Cobol85\n\n`Cobol85Preprocessor.g4` → `Cobol85.g4`. Ambos são combined grammars, entry rule `startRule`.\n\n")
                .append("### ProLeap Cobol\n\n`CobolPreprocessor.g4` → `Cobol.g4`. Também combined grammars, entry rule `startRule`; nenhuma dependência `proleap-cobol*` foi usada.\n\n")
                .append("Nenhum dos quatro arquivos declara `tokenVocab`, modes, semantic predicates, actions, opções especiais ou Java embutido. Listeners/visitors gerados são opcionais; o runner usa a API genérica de parse tree. Não há dependência externa de grammar.\n\n");
        r.append("## 4. Environment\n\n")
                .append("- Benchmark date: ").append(LocalDate.now()).append("\n\n- java.version: ").append(System.getProperty("java.version"))
                .append("\n\n- java.vendor: ").append(System.getProperty("java.vendor")).append("\n\n- os.name: ").append(System.getProperty("os.name"))
                .append("\n\n- os.version: ").append(System.getProperty("os.version")).append("\n\n- os.arch: ").append(System.getProperty("os.arch"))
                .append("\n\n- ANTLR tool/runtime: 4.13.2 for both candidates\n\n- Maven: 3.9.16\n\n- Java compilation target: 17\n\n");
        r.append("## 5. Corpus\n\n- Programs: ").append(data.programs().size()).append("\n\n- Copybooks supplied: ").append(data.copybooks().size())
                .append("\n\n- Program LOC / bytes: ").append(totalLoc).append(" / ").append(totalBytes)
                .append("\n\n- Copybook LOC / bytes: ").append(copyLoc).append(" / ").append(copyBytes)
                .append("\n\n- Min / median / max program LOC: ").append(sizes.get(0)).append(" / ").append(Statistics.median(sizes)).append(" / ").append(sizes.get(sizes.size()-1)).append("\n\n")
                .append("Source format: **FIXED**. A inspeção da coluna 7 encontrou indicadores de comentário (`*`) e 11 continuações (`-`); não foi detectado arquivo FREE. O normalizador remove sequence area (1–6), interpreta a coluna 7 e limita a área de programa a 8–72.\n\n")
                .append("Caracterização textual (número de programas contendo ao menos uma ocorrência; não usada semanticamente):\n\n")
                .append("| Construct | Files |\n|---|---:|\n");
        Map<String,Integer> inv = inventory(data.programs()); inv.forEach((k,v) -> r.append("| ").append(k).append(" | ").append(v).append(" |\n")); r.append('\n');
        r.append("## 6. Methodology\n\nCada frontend implementa a mesma interface `CobolFrontend`. Foram executados ").append(data.warmups()).append(" warmups e ").append(data.runs())
                .append(" runs medidos por frontend, sequencialmente. Tempos usam `System.nanoTime`; os CSVs por arquivo guardam a mediana. Estatísticas do corpus inteiro usam soma por run e depois mediana, p95 e média. Success exige zero lexer/parser syntax errors; uma árvore recuperada com erros é FAILED. Linhas de diagnostics do parser referem-se ao texto normalizado/expandido; diagnostics de COPY usam a posição no arquivo que contém a diretiva.\n\n")
                .append("O preprocessing é parse-tree-driven: a grammar correspondente reconhece `COPY`, `REPLACING` e `EXEC`; uma transformação comum resolve nomes case-insensitively em `cpy/`, tenta `.cpy`/`.CPY`, expande recursivamente e aplica pseudo-text `REPLACING`. COPY ausente vira `unresolved_copy`, nunca é criado ou ignorado silenciosamente. As quatro grammars oficiais são copiadas sem modificação para `target/antlr4` durante o build.\n\n");
        r.append("## 7. Preprocessor Results\n\n").append(preprocessorTable(a,b)).append('\n')
                .append("A métrica `preprocessed` exige parse do preprocessor sem erro e zero COPY não resolvido. O parser principal ainda é executado após substituir COPY ausente por comentário, permitindo separar capacidade da grammar de disponibilidade da biblioteca.\n\n")
                .append("COPYs ausentes (nomes únicos): ").append(unresolvedSummary(a)).append(". São layouts BMS/IBM ou copybooks de aplicação não fornecidos; nenhum arquivo sintético foi adicionado.\n\n")
                .append("`EXEC CICS`, `EXEC SQL` e `EXEC SQLIMS` são preservados como texto opaco em tokens marcados (`*>EXECCICS`, `*>EXECSQL`, `*>EXECSQLIMS`) e aparecem sob regras `exec*Statement`; não há análise da DSL. Os dois pares usam esse mesmo contrato léxico.\n\n");
        r.append("## 8. Parser Correctness Results\n\n").append(correctnessTable(a,b,totalLoc)).append('\n')
                .append("Arquivos problemáticos:\n\n").append(failures(a)).append(failures(b));
        r.append("## 9. Performance Results\n\n").append(performance(data, names.get(0))).append(performance(data,names.get(1)))
                .append("As medidas incluem lexing no tempo de parsing. Performance é secundária à correção; diferenças pequenas não mudam o veredito.\n\n");
        r.append("## 10. Memory Results\n\n").append(memory(a,b)).append("\nO valor é **pico de heap observado**, amostrado aproximadamente a cada 1 ms com `totalMemory-freeMemory`; não é RSS nem garantia do pico real. Não foi usado `System.gc()`. Como os frontends rodam no mesmo JVM, retenção/JIT pode influenciar a comparação.\n\n");
        r.append("## 11. Parse Tree Characteristics\n\n").append(treeTable(a,b)).append('\n')
                .append("Árvore menor ou menos profunda não implica automaticamente grammar melhor. Ambas expõem regras nomeadas para statements e clauses, adequadas a visitor próprio.\n\n");
        r.append("## 12. Qualitative Syntax Analysis\n\nMOVE, CALL, IF, EVALUATE, PERFORM, COMPUTE, SET, STRING, UNSTRING e INSPECT aparecem no corpus e são nós explícitos em ambas. COPY desaparece após expansão, corretamente pertencendo à fase de preprocessing. REDEFINES e OCCURS aparecem como clauses explícitas. A estrutura das duas grammars é muito próxima; `Cobol85.g4` é mais extensa, enquanto `Cobol.g4` contém permissividades úteis (por exemplo, ponto opcional em `paragraph` e zero ou mais `programUnit`).\n\n")
                .append("Amostras compactas reais (primeiro nó coletado, truncado):\n\n").append(samples(a,b));
        r.append("## 13. Procedure Division / CFG Suitability\n\nAmbas modelam `procedureDivisionBody → paragraphs + procedureSection*`, com `paragraph`, `sentence` e `statement` explícitos. IF separa `ifThen`/`ifElse`; EVALUATE separa selects, WHEN e OTHER; PERFORM separa inline de procedure e representa THRU; GO TO separa simple de DEPENDING ON. Isso permite identificar branches, alvos, fallthrough e limites de basic blocks sem parse textual. Entre elas, a árvore é essencialmente isomórfica; a escolha para CFG é dominada pela cobertura medida e pela permissividade de parágrafos, não por diferença estrutural grande.\n\n");
        r.append("## 14. Data Division / Symbol Resolution Suitability\n\nAmbas usam `dataDescriptionEntryFormat1/2/3`: level e name são filhos diretos, seguidos por clauses nomeadas para PIC, VALUE, REDEFINES, OCCURS, USAGE e demais atributos; level 66 representa RENAMES e 88 condition names. Parentage de 01/05/10 precisa ser reconstruída pela pilha de níveis no AstBuilder (não é nesting estrutural), mas level/name/picture/value/redefines/occurs/usage são extraíveis sem heurística textual. Não surgiu vantagem estrutural decisiva entre as duas.\n\n");
        r.append("## 15. CALL Representation\n\n").append(callAnalysis(data.programs())).append("\nNas duas grammars, `callStatement` contém alvo `(identifier | literal)`, `callUsingPhrase` e parâmetros separados em BY REFERENCE, BY VALUE e BY CONTENT. Portanto target, arguments e passing mode são diretamente visitáveis; as regras são praticamente idênticas.\n\n");
        r.append("## 16. Failure Analysis\n\n").append(failureAnalysis(a,b)).append('\n');
        r.append("## 17. Maintainability and Customization\n\n`Cobol.g4` tem 3.269 linhas versus 5.654 de `Cobol85.g4`; o preprocessor correspondente tem 670 versus 1.902. Menor tamanho favorece leitura, mas `Cobol85` contém cobertura lexical/sintática adicional. Nenhuma tem actions ou dependências runtime, portanto ambas são forkáveis. `potential_local_patch`: adicionar `COMMACHAR?` entre operands de `stringSendingPhrase` em `Cobol85.g4`, espelhando a regra já presente em `Cobol.g4`; isso provavelmente resolve o único arquivo falho, mas não foi aplicado ao benchmark. Construir preprocessing próprio é tecnicamente razoável: resolução de bibliotecas, formato fixo, conditional compilation e políticas de COPY são preocupações do ambiente e já exigem código host, enquanto as grammars de preprocessor apenas reconhecem sintaxe.\n\n");
        r.append("## 18. Limitations of This Experiment\n\nO corpus é pequeno, concentrado em uma aplicação CardDemo, com COPYs IBM/BMS ausentes; não representa todo COBOL empresarial. A normalização FIXED e transformação EXEC são código do spike, embora comuns aos candidatos. Medição no mesmo JVM não isola completamente JIT/GC. Constructs ausentes ou raros não autorizam conclusão ampla. O experimento não valida semântica, layout, SQL/CICS, AST ou CFG.\n\n");
        r.append("## 19. Verdict\n\nRECOMMENDATION: ").append(recommendation).append("\n\n### Why\n\n").append(why(recommendation,a,b))
                .append("\n### Main trade-offs\n\nO candidato recomendado deve ser lido como a melhor baseline neste corpus. O outro pode ter regras pontualmente mais estritas ou cobertura de dialect features que mereçam cherry-pick posterior; o preprocessor pode ser substituído independentemente.\n\n")
                .append("### What this does NOT prove\n\nNão prova cobertura universal de COBOL, nem qualidade semântica, nem que patches locais devam ser incorporados antes de um corpus maior.\n\n")
                .append("### Recommended architecture\n\n```text\nCOBOL\n  ↓\npreprocessor próprio, usando as regras atuais como referência e mantendo COPY/EXEC diagnosticáveis\n  ↓\n").append(recommendation.equals("Cobol85.g4") ? "Cobol85.g4" : recommendation.equals("Cobol.g4") ? "Cobol.g4" : "candidate grammar after broader corpus")
                .append("\n  ↓\nANTLR Parse Tree\n  ↓\nour AstBuilder\n  ↓\nour AST\n  ↓\nour CFG\n  ↓\nour dataflow analyses\n```\n\n");
        r.append("## 20. Recommended Next Step\n\nAdicionar um corpus estratificado do banco (dialetos, DB2/CICS/IMS, copybooks de sistema e formatos mistos), congelá-lo, repetir sem patches e só depois criar uma branch experimental com cada `potential_local_patch`. Construir primeiro um AstBuilder fino para Data Division, CALL e control flow no candidato recomendado.\n\n")
                .append("### Explicit answers to the evaluation questions\n\n").append(explicitAnswers(data,a,b,recommendation));
        r.append("## Provenance\n\n| File | SHA-256 | Local/upstream provenance |\n|---|---|---|\n");
        for (String g : List.of("Cobol85.g4","Cobol85Preprocessor.g4","Cobol.g4","CobolPreprocessor.g4"))
            r.append("| `").append(g).append("` | `").append(sha(data.root().resolve(g))).append("` | Local candidate; header attributes Ulrich Wolffgang/proleap.io and names the associated upstream project |\n");
        Files.writeString(data.root().resolve("benchmark/REPORT.md"), r, StandardCharsets.UTF_8);
    }

    private static String summaryLine(List<FrontendResult> f) { return f.get(0).frontend()+" preprocessed "+okPrep(f)+"/"+f.size()+" and parsed "+okParse(f)+"/"+f.size(); }
    private static long okPrep(List<FrontendResult> f){return f.stream().filter(FrontendResult::preprocessingSuccess).count();}
    private static long okParse(List<FrontendResult> f){return f.stream().filter(FrontendResult::parsingSuccess).count();}
    private static String recommendation(List<FrontendResult>a,List<FrontendResult>b){long ap=okParse(a),bp=okParse(b); if(ap!=bp)return ap>bp?"Cobol85.g4":"Cobol.g4"; int ae=syntax(a),be=syntax(b); if(ae!=be)return ae<be?"Cobol85.g4":"Cobol.g4"; return "Cobol.g4";}
    private static int syntax(List<FrontendResult> f){return f.stream().mapToInt(x->x.lexerErrors()+x.parserErrors()).sum();}
    private static String preprocessorTable(List<FrontendResult>a,List<FrontendResult>b){return "| Frontend | Preprocessed | ANTLR preprocessor errors | Unresolved COPY |\n|---|---:|---:|---:|\n"+rowPrep(a)+rowPrep(b);}
    private static String rowPrep(List<FrontendResult>f){return "| "+f.get(0).frontend()+" | "+okPrep(f)+"/"+f.size()+" | "+f.stream().mapToInt(FrontendResult::preprocessingErrors).sum()+" | "+f.stream().mapToInt(FrontendResult::unresolvedCopies).sum()+" |\n";}
    private static String correctnessTable(List<FrontendResult>a,List<FrontendResult>b,long loc){return "| Frontend | Parse success | Lexer errors | Parser errors | Errors/KLOC |\n|---|---:|---:|---:|---:|\n"+rowCorrect(a,loc)+rowCorrect(b,loc);}
    private static String rowCorrect(List<FrontendResult>f,long loc){return "| "+f.get(0).frontend()+" | "+okParse(f)+"/"+f.size()+" | "+f.stream().mapToInt(FrontendResult::lexerErrors).sum()+" | "+f.stream().mapToInt(FrontendResult::parserErrors).sum()+" | "+ResultWriter.fmt(syntax(f)/(loc/1000.0))+" |\n";}
    private static String failures(List<FrontendResult>f){StringBuilder s=new StringBuilder("**"+f.get(0).frontend()+"**\n\n"); List<FrontendResult> bad=f.stream().filter(x->!x.parsingSuccess()).toList(); if(bad.isEmpty())return s.append("- Nenhuma falha de parser.\n\n").toString(); for(var x:bad){Diagnostic d=x.diagnostics().stream().filter(q->q.phase()==Diagnostic.Phase.LEXER||q.phase()==Diagnostic.Phase.PARSER).findFirst().orElse(null);s.append("- `").append(x.file()).append("`: ").append(x.lexerErrors()).append(" lexer + ").append(x.parserErrors()).append(" parser errors");if(d!=null)s.append("; first: ").append(shortMessage(d.message())).append(" near `").append(d.offendingToken()).append("`");s.append(".\n");}return s.append('\n').toString();}
    private static String shortMessage(String message){return message.length()<=220?message:message.substring(0,217)+"...";}
    private static String unresolvedSummary(List<FrontendResult> f){return f.stream().flatMap(x->x.diagnostics().stream()).map(Diagnostic::message).filter(x->x.startsWith("unresolved_copy: ")).map(x->"`"+x.substring(17)+"`").distinct().sorted().collect(java.util.stream.Collectors.joining(", "));}
    private static String performance(BenchmarkData d,String n){var runs=d.measuredRuns().get(n);var p=ResultWriter.corpusTotals(runs,0);var q=ResultWriter.corpusTotals(runs,1);var t=ResultWriter.corpusTotals(runs,2);long loc=d.aggregateFiles().get(n).stream().mapToLong(FrontendResult::sourceLines).sum();double sec=Statistics.median(t)/1e9;return "**"+n+"**: preprocessing median/p95/mean "+ResultWriter.ms(Statistics.median(p))+" / "+ResultWriter.ms(Statistics.p95(p))+" / "+ResultWriter.ms(Statistics.mean(p))+" ms; parsing "+ResultWriter.ms(Statistics.median(q))+" / "+ResultWriter.ms(Statistics.p95(q))+" / "+ResultWriter.ms(Statistics.mean(q))+" ms; total "+ResultWriter.ms(Statistics.median(t))+" / "+ResultWriter.ms(Statistics.p95(t))+" / "+ResultWriter.ms(Statistics.mean(t))+" ms; "+ResultWriter.fmt(loc/sec)+" LOC/s.\n\n";}
    private static String memory(List<FrontendResult>a,List<FrontendResult>b){return "| Frontend | Max observed heap bytes |\n|---|---:|\n| "+a.get(0).frontend()+" | "+a.stream().mapToLong(FrontendResult::approximatePeakUsedHeapBytes).max().orElse(0)+" |\n| "+b.get(0).frontend()+" | "+b.stream().mapToLong(FrontendResult::approximatePeakUsedHeapBytes).max().orElse(0)+" |\n";}
    private static String treeTable(List<FrontendResult>a,List<FrontendResult>b){return "| Frontend | Tokens | Tree nodes | Max depth |\n|---|---:|---:|---:|\n"+treeRow(a)+treeRow(b);}
    private static String treeRow(List<FrontendResult>f){return "| "+f.get(0).frontend()+" | "+f.stream().mapToLong(FrontendResult::tokenCount).sum()+" | "+f.stream().mapToLong(FrontendResult::parseTreeNodeCount).sum()+" | "+f.stream().mapToInt(FrontendResult::parseTreeMaxDepth).max().orElse(0)+" |\n";}
    private static String samples(List<FrontendResult>a,List<FrontendResult>b){StringBuilder s=new StringBuilder();for(var f:List.of(a,b)){String sample=f.stream().map(FrontendResult::parseTreeSample).filter(x->!x.isBlank()).findFirst().orElse("no sample");s.append("**").append(f.get(0).frontend()).append("**\n\n```text\n").append(sample.substring(0,Math.min(1200,sample.length()))).append("\n```\n\n");}return s.toString();}
    private static String failureAnalysis(List<FrontendResult>a,List<FrontendResult>b){int am=maxErrors(a),bm=maxErrors(b);return "COPYs ausentes são falha de preprocessing, não da grammar. O único parser failure residual ocorre em `COACTUPC.cbl`: seis vírgulas entre operands de dois `STRING`. `Cobol.g4` aceita `stringSending (COMMACHAR? stringSending)*`; `Cobol85.g4` exige `stringSending+` sem vírgula. É uma incompatibilidade localizada, não seis features distintas, e constitui `potential_local_patch`. Maior contagem em um arquivo: "+a.get(0).frontend()+"="+am+", "+b.get(0).frontend()+"="+bm+". "+(am>bm*2?"Cobol85 apresentou uma cascata localizada pior; os seis diagnostics provêm do mesmo padrão sintático.":bm>am*2?"Cobol apresentou cascata significativamente pior.":"Não houve diferença de cascata superior a 2× pelo critério adotado.")+" As grammars oficiais permaneceram intactas.\n";}
    private static int maxErrors(List<FrontendResult>f){return f.stream().mapToInt(x->x.lexerErrors()+x.parserErrors()).max().orElse(0);}
    private static String why(String rec,List<FrontendResult>a,List<FrontendResult>b){List<FrontendResult>w=rec.equals("Cobol85.g4")?a:b,o=rec.equals("Cobol85.g4")?b:a;return "1. Cobertura: "+okParse(w)+"/"+w.size()+" contra "+okParse(o)+"/"+o.size()+".\n2. Syntax errors: "+syntax(w)+" contra "+syntax(o)+".\n3. As árvores têm estrutura semelhante para AST/CFG/Data Division/CALL; portanto cobertura decide antes de microdiferenças de tempo.\n";}
    private static Map<String,Integer> inventory(List<Path>files)throws IOException{Map<String,Integer>m=new LinkedHashMap<>();for(String k:INVENTORY)m.put(k,0);for(Path p:files){String x=codeText(p).toUpperCase(Locale.ROOT);for(String k:INVENTORY)if(Pattern.compile("\\b"+k.replace(" ","\\s+")+"\\b").matcher(x).find())m.compute(k,(q,v)->v+1);}return m;}
    private static String callAnalysis(List<Path>files)throws IOException{int literal=0,variable=0,using=0,ref=0,content=0,value=0;Pattern call=Pattern.compile("(?i)\\bCALL\\s+([^\\s.]+)([^.]*)");for(Path p:files){Matcher m=call.matcher(codeText(p));while(m.find()){if(m.group(1).startsWith("'")||m.group(1).startsWith("\""))literal++;else variable++;String tail=m.group(2).toUpperCase(Locale.ROOT);if(tail.contains("USING"))using++;if(tail.contains("BY REFERENCE"))ref++;if(tail.contains("BY CONTENT"))content++;if(tail.contains("BY VALUE"))value++;}}return "Classificação textual das ocorrências: CALL literal="+literal+", CALL variável="+variable+", CALL USING="+using+", explicit BY REFERENCE="+ref+", BY CONTENT="+content+", BY VALUE="+value+".\n";}
    private static String explicitAnswers(BenchmarkData d,List<FrontendResult>a,List<FrontendResult>b,String rec){String fast=faster(d,a.get(0).frontend(),b.get(0).frontend());String lowHeap=a.stream().mapToLong(FrontendResult::approximatePeakUsedHeapBytes).max().orElse(0)<=b.stream().mapToLong(FrontendResult::approximatePeakUsedHeapBytes).max().orElse(0)?a.get(0).frontend():b.get(0).frontend();return "1. Preprocessing: "+okPrep(a)+"/"+a.size()+" e "+okPrep(b)+"/"+b.size()+"; empate dos preprocessors.\n2. Parsing sem syntax errors: "+okParse(a)+"/"+a.size()+" e "+okParse(b)+"/"+b.size()+".\n3. Falha: `COACTUPC.cbl` apenas em Cobol85; Cobol não falhou.\n4–5. Construct causador: `STRING` com vírgulas; é diferença da grammar. COPYs ausentes são preprocessing separado.\n6. Cobol85 gerou seis diagnostics do mesmo padrão; Cobol, zero.\n7. AstBuilder: estruturas quase isomórficas; "+rec+" vence pela cobertura.\n8. CFG: ambas estruturam IF/EVALUATE/PERFORM/GO TO; "+rec+" é a baseline.\n9. Data Division: empate estrutural; clauses nomeadas em ambas.\n10. CALL: empate estrutural; target e passing modes explícitos.\n11. EXEC DSLs: tratamento opaco equivalente, preservado em nós exec.\n12. Mais rápida no total mediano: "+fast+".\n13. Menor pico de heap observado: "+lowHeap+" (com viés de ordem/JVM compartilhada).\n14. A diferença de performance é pequena frente à diferença de correção e não altera a decisão.\n15. `potential_local_patch`: vírgula opcional em `Cobol85.stringSendingPhrase`; não aplicado.\n16. `Cobol.g4` é menor e, neste corpus, mais simples de manter como fork.\n17. Faz sentido construir preprocessor próprio e manter as regras atuais como referência.\n18. Baseline recomendada: **"+rec+"**.\n";}
    private static String codeText(Path p)throws IOException{StringBuilder s=new StringBuilder();for(String line:Files.readAllLines(p)){if(line.length()>6&&(line.charAt(6)=='*'||line.charAt(6)=='/'))continue;s.append(line).append('\n');}return s.toString();}
    private static String faster(BenchmarkData d,String a,String b){long av=Statistics.median(ResultWriter.corpusTotals(d.measuredRuns().get(a),2));long bv=Statistics.median(ResultWriter.corpusTotals(d.measuredRuns().get(b),2));return av<=bv?a:b;}
    private static String sha(Path p)throws IOException{try{byte[]h=MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(p));return HexFormat.of().formatHex(h);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
